quadtree.pseudocode:
class QuadTree:  # PR 쿼드트리
    def __init__(self, box, cap=4):
        self.box, self.cap = box, cap  # box=(x0,y0,x1,y1)
        self.points, self.kids = [], None

    def insert(self, p):
        if not contains(self.box, p):
            return False
        if self.kids is None:
            if len(self.points) < self.cap:
                self.points.append(p)
                return True
            self.split()  # 용량 초과 → 4분할
        return any(k.insert(p) for k in self.kids)

    def split(self):
        x0, y0, x1, y1 = self.box
        mx, my = (x0 + x1) / 2, (y0 + y1) / 2
        self.kids = [QuadTree(b, self.cap) for b in (
            (x0, my, mx, y1), (mx, my, x1, y1),  # NW, NE
            (x0, y0, mx, my), (mx, y0, x1, my))]  # SW, SE
        for q in self.points:  # 기존 점 재배치
            any(k.insert(q) for k in self.kids)
        self.points = []

queue.pseudocode:
class CircularQueue:
    def __init__(self, n):
        self.q = [None] * n
        self.n = n
        # 한 칸을 비워 포화·공백을 구분
        self.front = self.rear = 0

    def enqueue(self, x):
        nxt = (self.rear + 1) % self.n
        if nxt == self.front:
            raise OverflowError  # 포화
        self.rear = nxt
        self.q[self.rear] = x

    def dequeue(self):
        if self.front == self.rear:
            raise IndexError  # 공백
        self.front = (self.front + 1) % self.n
        return self.q[self.front]
